BEGIN READ ONLY;
DO $target$ BEGIN if (select system_identifier::text from pg_catalog.pg_control_system())<>'7642734024280108049' then raise exception 'Wrong target cluster';end if;END $target$;
DO $post$ DECLARE nw11_metadata jsonb; BEGIN
 if not exists(select 1 from supabase_migrations.schema_migrations where version='20261015230935') then raise exception 'NW11 integration version is not installed: inspect failure before retrying';end if;
